#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT Shape : 4
COMPONENT Lighting : 3
COMPONENT CubeMapTexturing : 3
COMPONENT Texturing : 3
COMPONENT Scripting : 1
COMPONENT KeyDeviceSensor : 1
COMPONENT EnvironmentalEffects : 3
COMPONENT Grouping : 3
COMPONENT X_ITE : 1

Viewpoint {
  position 0 0 6
}

Background {
  skyColor 0.15 0.15 0.18
}

EnvironmentLight {
  specularTexture ImageCubeMapTexture {
    url "../synthetic-rea-b02/pbr/env.png"
  }
}

DirectionalLight {
  color 1 0.95 0.9
  intensity 0.8
  direction -0.4 -0.6 -0.7
}

PointLight {
  color 0.6 0.8 1
  intensity 2
  attenuation 0 0 1
  location 2.5 2 3
  radius 20
}

Transform {
  translation 0 0 -3
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 1 1 1
      }
      texture ImageTexture {
        url "../synthetic-rea-b03/proj-checker.png"
      }
    }
    geometry Box {
      size 8 6 0.1
    }
  }
}

Transform {
  translation -1.5 0.8 -1.5
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 1 0.2 0.2
      }
    }
    geometry Box {
      size 0.6 2.5 0.3
    }
  }
}

DEF DT1 DiffuseTransmissionMaterialExtension {
  diffuseTransmission 1
  diffuseTransmissionColor 1 0.7 0.5
}

DEF VO1 VolumeMaterialExtension {
  thickness 0.4
  attenuationDistance 0.6
  attenuationColor 1 0.8 0.6
}

DEF VS1 VolumeScatterMaterialExtension {
  multiscatterColor 0.9 0.5 0.3
}

DEF VS3 VolumeScatterMaterialExtension {
  multiscatterColor 0.2 0.4 0.9
  multiscatterColorTexture ImageTexture {
    url "../synthetic-rea-b02/pbr/base.png"
  }
}

DEF M1 PhysicalMaterial {
  baseColor 0.9 0.8 0.7
  metallic 0
  roughness 0.6
  extensions [
    USE DT1
    USE VO1
    USE VS1
  ]
}

DEF M2 PhysicalMaterial {
  baseColor 0.9 0.8 0.7
  metallic 0
  roughness 0.6
  extensions [
    USE DT1
    USE VO1
  ]
}

DEF M3 PhysicalMaterial {
  baseColor 0.9 0.8 0.7
  metallic 0
  roughness 0.6
  extensions [
    USE DT1
    USE VO1
    USE VS3
  ]
}

DEF G1 Group {
  children DEF S1 Transform {
    translation -1.5 0.8 0
    children Shape {
      appearance Appearance {
        material USE M1
      }
      geometry Sphere {
        radius 0.6
      }
    }
  }
}

DEF S2 Transform {
  translation 0 0.8 0
  children Shape {
    appearance Appearance {
      material USE M2
    }
    geometry Sphere {
      radius 0.6
    }
  }
}

DEF S3 Transform {
  translation 1.5 0.8 0
  children Shape {
    appearance Appearance {
      material USE M3
    }
    geometry Sphere {
      radius 0.6
    }
  }
}

DEF K KeySensor { }

DEF R Script {
  inputOnly      SFString on_key
  inputOutput    SFString log ""
  initializeOnly SFNode   vs1 USE VS1
  initializeOnly SFNode   vs3 USE VS3
  initializeOnly SFNode   vo1 USE VO1
  initializeOnly SFNode   dt1 USE DT1
  initializeOnly SFNode   m1 USE M1
  initializeOnly SFNode   m2 USE M2
  initializeOnly SFNode   m3 USE M3
  initializeOnly SFNode   g1 USE G1
  initializeOnly SFNode   s1 USE S1

  url "javascript:
var made = null;
function on_key (k)
{
   log = log + 'K' + k + ' ';
   if (k == 'a') vs1 .multiscatterColor = new SFColor (0.1, 0.9, 0.2);
   if (k == 'b') vo1 .attenuationDistance = 2;
   if (k == 'c') dt1 .diffuseTransmissionColor = new SFColor (0.3, 0.5, 1);
   if (k == 'd') { made = Browser .currentScene .createNode ('VolumeScatterMaterialExtension'); made .multiscatterColor = new SFColor (0.8, 0.8, 0.2); m2 .extensions = new MFNode (dt1, vo1, made); }
   if (k == 'e') made .multiscatterColor = new SFColor (0.1, 0.3, 0.9);
   if (k == 'f') m1 .extensions = new MFNode (dt1, vo1);
   if (k == 'g') vs3 .multiscatterColorTexture = Browser .currentScene .createNode ('PixelTexture');
   if (k == 'h') { var p = vs3 .multiscatterColorTexture; p .image = new SFImage (2, 2, 3, new MFInt32 (0xff0000, 0x00ff00, 0x0000ff, 0xffff00)); }
   if (k == 'i') vs1 .scatterStrength = 0.2;
   if (k == 'j') m3 .extensions = new MFNode ();
   if (k == 'k') g1 .removeChildren = new MFNode (s1);
   if (k == 'l') g1 .addChildren = new MFNode (s1);
   if (k == 'm') m1 .extensions = new MFNode (dt1, vo1, vs1);
   if (k == 'n') vo1 .attenuationDistance = 0.1;
   if (k == 'o') m3 .metallic = 1;
}
"
  directOutput TRUE
}

ROUTE K.keyPress TO R.on_key

